begin;

alter function "Basic_Carrier_Record".get_operational_freight_planning(text,uuid) rename to get_operational_freight_planning_freighter;
revoke all on function "Basic_Carrier_Record".get_operational_freight_planning_freighter(text,uuid) from public,anon,authenticated;

create or replace function "Basic_Carrier_Record".get_operational_freight_planning(p_iata text,p_operational_flight_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare f "Basic_Carrier_Record"."Operational_Flights"%rowtype; aircraft "Basic_Carrier_Record"."Basic_Aircraft_Data"%rowtype; passenger jsonb; pax jsonb; assumption record; can_operate boolean; base_weight numeric; crew_adjustment numeric:=0; pantry_adjustment numeric:=0; planning_weight numeric; maximum_zfw numeric; maximum_payload numeric; passenger_weight numeric:=0; baggage_weight numeric:=0; baggage_volume numeric:=0; class_baggage_weight numeric; class_baggage_volume numeric; booked integer; baggage_density numeric; cargo_density numeric; hold_weight numeric:=0; hold_volume numeric:=0; remaining_payload numeric; remaining_hold_weight numeric; remaining_hold_volume numeric; offer numeric; limiting text; hold_system text; uld_count integer:=0; uld_code text; uld_tare numeric:=0; uld_max_weight numeric:=0; uld_volume numeric:=0; baggage_uld_positions integer:=0; available_uld_positions integer:=0; uld_space_weight numeric:=0; bulk_weight numeric:=0; bulk_volume numeric:=0; bulk_planning_weight numeric:=0; total_available_volume numeric:=0; available_space_weight numeric:=0; position_groups jsonb:='[]'::jsonb; bulk_holds jsonb:='[]'::jsonb; missing jsonb:='[]'::jsonb;
begin
 p_iata:=upper(btrim(p_iata));
 if (select auth.uid()) is null or not(private.has_carrier_permission(p_iata,'LOAD_CONTROL_VIEW') or private.has_global_permission('LOAD_CONTROL_VIEW')) then raise exception 'Load Control access denied' using errcode='42501';end if;
 can_operate:=private.has_carrier_permission(p_iata,'LOAD_CONTROL_OPERATE') or private.has_global_permission('LOAD_CONTROL_OPERATE');
 select * into f from "Basic_Carrier_Record"."Operational_Flights" where "Carrier_IATA"=p_iata and "Operational_Flight_ID"=p_operational_flight_id;
 if not found then raise exception 'Operational flight not found' using errcode='P0002';end if;
 select * into aircraft from "Basic_Carrier_Record"."Basic_Aircraft_Data" where "Carrier_IATA"=p_iata and "Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and "Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype";
 if not found then raise exception 'Aircraft configuration not found' using errcode='23503';end if;
 if aircraft."Aircraft_Operating_Role"='FREIGHTER' then return "Basic_Carrier_Record".get_operational_freight_planning_freighter(p_iata,p_operational_flight_id);end if;

 if f."Aircraft_Registration" is null then base_weight:=aircraft."Standard_Fleet_Weight";else select case when aircraft."Start_Weight_Principle"='DRY_OPERATING_WEIGHT' then x."Dry_Operating_Weight" else x."Basic_Weight" end into base_weight from "Basic_Carrier_Record"."Carrier_Aircraft_Fleet" x where x."Carrier_IATA"=p_iata and x."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and x."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and btrim(x."Aircraft_Registration")=btrim(f."Aircraft_Registration") limit 1;end if;
 if aircraft."Start_Weight_Principle"='DRY_OPERATING_WEIGHT' then
  select coalesce(max(c."DOW_Weight_Adjustment"),0) into crew_adjustment from "Basic_Carrier_Record"."Aircraft_Crew_Codes" c where c."Carrier_IATA"=p_iata and c."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and c."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and btrim(c."Crew_Code_ID")=btrim(f."Crew_Code_ID");
  select coalesce(max(c."DOW_Weight_Adjustment"),0) into pantry_adjustment from "Basic_Carrier_Record"."Aircraft_Pantry_Codes" c where c."Carrier_IATA"=p_iata and c."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and c."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and btrim(c."Pantry_Code_ID")=btrim(f."Pantry_Code_ID");
  planning_weight:=base_weight+crew_adjustment+pantry_adjustment;
 end if;
 select coalesce((select w."Zero_Fuel_Weight" from "Basic_Carrier_Record"."Aircraft_Limiting_Weight_Values" w where w."Carrier_IATA"=p_iata and w."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and w."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and w."Table_Name"='ALL' and w."Carrier_Variant_Code"=f."Aircraft_Series_Subtype" and (w."Aircraft_Registration" is null or btrim(w."Aircraft_Registration")=btrim(f."Aircraft_Registration")) order by (w."Aircraft_Registration" is not null) desc limit 1),aircraft."MZFW") into maximum_zfw;
 maximum_payload:=greatest(0,maximum_zfw-planning_weight);

 passenger:="Basic_Carrier_Record".get_operational_passenger_booking(p_iata,p_operational_flight_id);passenger_weight:=coalesce((passenger->>'totalPassengerWeight')::numeric,0);
 select u."Density_Checked_Baggage"::numeric,u."Density_General_Cargo"::numeric into baggage_density,cargo_density from "Basic_Carrier_Record"."Carrier_Units_of_Measure" u where u."Carrier_IATA"=p_iata;
 for pax in select value from jsonb_array_elements(coalesce(passenger->'classes','[]'::jsonb)) loop
  booked:=coalesce((pax->>'booked')::integer,0);
  select q.* into assumption from(
   select p.*,1 priority from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where p."Carrier_IATA"=p_iata and p."Class_Code"=pax->>'code' and ((f."Baggage_Weight_Basis"='VARIATION' and p."Flight_Type_Variation"=f."Baggage_Flight_Variation") or (f."Baggage_Weight_Basis"<>'VARIATION' and p."Flight_Type_Variation" is null))
   union all select p.*,2 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where f."Baggage_Weight_Basis"='VARIATION' and p."Carrier_IATA"=p_iata and p."Class_Code" is null and p."Flight_Type_Variation"=f."Baggage_Flight_Variation"
   union all select p.*,3 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where f."Baggage_Weight_Basis"='VARIATION' and p."Carrier_IATA"=p_iata and p."Class_Code"=pax->>'code' and p."Flight_Type_Variation" is null
   union all select p.*,9 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where p."Carrier_IATA"=p_iata and p."Class_Code" is null and p."Flight_Type_Variation" is null order by priority limit 1
  )q;
  class_baggage_weight:=case when assumption."Average_Bag_Weight_Per_Passenger" is null then null else booked*assumption."Average_Bag_Weight_Per_Passenger" end;
  class_baggage_volume:=case when assumption."Average_Bag_Volume" is not null then booked*coalesce(assumption."Average_Bags_Per_Passenger",1)*assumption."Average_Bag_Volume" when baggage_density>0 and class_baggage_weight is not null then class_baggage_weight/baggage_density else null end;
  if class_baggage_weight is null then missing:=missing||jsonb_build_array('BAGGAGE_WEIGHT_'||(pax->>'code'));else baggage_weight:=baggage_weight+class_baggage_weight;end if;
  if class_baggage_volume is null then missing:=missing||jsonb_build_array('BAGGAGE_VOLUME_'||(pax->>'code'));else baggage_volume:=baggage_volume+class_baggage_volume;end if;
 end loop;

 select coalesce(sum(h."Hold_MAX_Weight"),0),coalesce(sum(h."Hold_MAX_Volume"),0),case when bool_or(h."Hold_Type"='ULD') and bool_or(h."Hold_Type"='BLK') then 'MIXED' when bool_or(h."Hold_Type"='ULD') then 'ULD' else 'BULK' end into hold_weight,hold_volume,hold_system from "Basic_Carrier_Record"."Aircraft_Holds" h where h."Carrier_IATA"=p_iata and h."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and h."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype";
 select count(*)::integer into uld_count from "Basic_Carrier_Record"."Carrier_ULD_Positions" p where p."Carrier_IATA"=p_iata and p."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and p."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and p."ULD_Row_Type"='POSITION';
 select btrim(s."ULD_ID"),s."ULD_Tare_Weight",s."ULD_Max_Weight",m."ULD_Volume" into uld_code,uld_tare,uld_max_weight,uld_volume from "Basic_Carrier_Record"."Carrier_ULD_Specifications" s left join "Basic_Carrier_Record"."MASTER_ULD_List" m on m."ULD_ID"=coalesce(s."Master_ULD_ID",s."ULD_ID") where s."Carrier_IATA"=p_iata and s."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and s."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" order by s."ULD_Default" desc,s."ULD_ID" limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('deck','LOWER','uldType',q.uld_type,'uldCode',q.uld_code,'positionCount',q.position_count,'maximumWeight',q.maximum_weight)),'[]'::jsonb) into position_groups from(select btrim(p."ULD_Type") uld_type,btrim(p."ULD_Code") uld_code,count(*)::integer position_count,sum(p."ULD_Position_Max_Weight") maximum_weight from "Basic_Carrier_Record"."Carrier_ULD_Positions" p where p."Carrier_IATA"=p_iata and p."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and p."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and p."ULD_Row_Type"='POSITION' group by btrim(p."ULD_Type"),btrim(p."ULD_Code"))q;
 select coalesce(jsonb_agg(jsonb_build_object('holdId',btrim(h."Hold_Name_ID"),'name',btrim(coalesce(h."Hold_Display_Name",h."Hold_Name_ID")),'maximumWeight',h."Hold_MAX_Weight",'volume',h."Hold_MAX_Volume",'planningWeight',least(h."Hold_MAX_Weight",round(h."Hold_MAX_Volume"*cargo_density))) order by h."Hold_Name_ID"),'[]'::jsonb) into bulk_holds from "Basic_Carrier_Record"."Aircraft_Holds" h where h."Carrier_IATA"=p_iata and h."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and h."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and h."Hold_Type"='BLK';
 select coalesce(sum(h."Hold_MAX_Weight"),0),coalesce(sum(h."Hold_MAX_Volume"),0) into bulk_weight,bulk_volume from "Basic_Carrier_Record"."Aircraft_Holds" h where h."Carrier_IATA"=p_iata and h."Aircraft_Type_IATA"=f."Aircraft_Type_IATA" and h."Aircraft_Series_Subtype"=f."Aircraft_Series_Subtype" and h."Hold_Type"='BLK';

 baggage_uld_positions:=case when uld_count=0 then 0 when coalesce(uld_volume,0)<=0 or coalesce(uld_max_weight-uld_tare,0)<=0 then uld_count else greatest(ceil(baggage_volume/uld_volume),ceil(baggage_weight/(uld_max_weight-uld_tare)))::integer end;
 available_uld_positions:=greatest(0,uld_count-baggage_uld_positions);uld_space_weight:=available_uld_positions*greatest(0,uld_max_weight-uld_tare);bulk_planning_weight:=case when bulk_volume<=0 then 0 when cargo_density is null then bulk_weight else least(bulk_weight,bulk_volume*cargo_density) end;total_available_volume:=available_uld_positions*coalesce(uld_volume,0)+bulk_volume;available_space_weight:=uld_space_weight+bulk_planning_weight;
 remaining_payload:=greatest(0,maximum_payload-passenger_weight-baggage_weight);remaining_hold_weight:=available_space_weight;remaining_hold_volume:=total_available_volume;offer:=least(remaining_payload,available_space_weight);
 limiting:=case when offer=remaining_payload then 'PAYLOAD' else 'HOLD_WEIGHT' end;
 if base_weight is null then missing:=missing||jsonb_build_array('AIRCRAFT_WEIGHT');end if;if maximum_zfw is null then missing:=missing||jsonb_build_array('MZFW');end if;if passenger->>'status'<>'BOOKED' then missing:=missing||jsonb_build_array('BOOKED_PASSENGERS');end if;if cargo_density is null then missing:=missing||jsonb_build_array('CARGO_DENSITY');end if;if hold_weight<=0 or hold_volume<=0 then missing:=missing||jsonb_build_array('LOWER_DECK_CAPACITY');end if;
 return jsonb_build_object('applicable',true,'operatingRole',aircraft."Aircraft_Operating_Role",'canEdit',can_operate,'version',f."Version",'weightBasis',case when f."Aircraft_Registration" is null then 'FLEET_WEIGHT' else 'REGISTRATION' end,'registration',f."Aircraft_Registration",'crewCode',f."Crew_Code_ID",'pantryCode',f."Pantry_Code_ID",'startWeightPrinciple',aircraft."Start_Weight_Principle",'fleetWeight',aircraft."Standard_Fleet_Weight",'planningAircraftWeight',planning_weight,'crewWeightAdjustment',crew_adjustment,'pantryWeightAdjustment',pantry_adjustment,'mzfw',maximum_zfw,'structuralCapacity',maximum_payload,'cargoPlanningDensity',cargo_density,'uldPositionGroups',position_groups,'uldWeightCapacity',hold_weight,'bulkHolds',bulk_holds,'bulkWeightCapacity',bulk_weight,'spaceWeightCapacity',available_space_weight,'cargoOfferWeight',offer,'limitingFactor',limiting,'ready',jsonb_array_length(missing)=0,'missing',missing,'registrationOptions','[]'::jsonb,'crewOptions','[]'::jsonb,'pantryOptions','[]'::jsonb,'maximumPayload',maximum_payload,'passengerWeight',passenger_weight,'plannedBaggageWeight',baggage_weight,'plannedBaggageVolume',round(baggage_volume,2),'holdWeightCapacity',hold_weight,'holdVolumeCapacity',hold_volume,'remainingPayload',remaining_payload,'remainingHoldWeight',remaining_hold_weight,'remainingHoldVolume',round(remaining_hold_volume,2),'holdSystem',hold_system,'uldPositionCount',uld_count,'uldCode',uld_code,'plannedBaggageUldPositions',baggage_uld_positions,'availableUldPositions',available_uld_positions,'availableBulkWeight',round(bulk_planning_weight),'availableBulkVolume',round(bulk_volume,2),'totalAvailableCargoVolume',round(total_available_volume,2));
end $$;

revoke all on function "Basic_Carrier_Record".get_operational_freight_planning(text,uuid) from public,anon;
grant execute on function "Basic_Carrier_Record".get_operational_freight_planning(text,uuid) to authenticated;
notify pgrst,'reload schema';
commit;
